New-DynamicDistributionGroup -Name "orthoct.hoppercomms" -Alias "orthoct.hoppercomms" -PrimarySMTPAddress "orthoct.hoppercomms@myorthoct.com" -RecipientFilter {(RecipientTypeDetails -eq 'UserMailbox' -and AccountDisabled -eq $false)}
Set-DynamicDistributionGroup -identity "sos.hoppercomms" -HiddenFromAddressListsEnabled $true -RequireSenderAuthenticationEnabled $false -AcceptMessagesOnlyFrom "hopco@service-now.com" -RecipientFilter {(RecipientTypeDetails -eq 'UserMailbox' -and AccountDisabled -eq $false -and Company -eq 'SOS')}
